values
  ('c1500000-0000-4000-8000-000000000001', 'organization_intro', 'Campanha editorial', 'Hero com mensagem forte, fotografia protagonista e ações claras, pensado para causar uma boa primeira impressão.', null, true, 'public', 'published'),
  ('c1500000-0000-4000-8000-000000000002', 'impact_metrics', 'Resultados em linha', 'Indicadores contínuos com hierarquia forte e leitura rápida, inspirados em faixas de impacto de sites institucionais.', null, true, 'public', 'published'),
