  ('c1500000-0000-4000-8000-000000000004', 'support_actions', 'Ações com destaque', 'Caminhos de participação em cards claros, com uma ação principal visualmente reconhecível.', null, true, 'public', 'published'),
  ('c1500000-0000-4000-8000-000000000005', 'custom_content', 'Missão, visão e valores', 'Três princípios institucionais organizados como uma composição editorial pronta para personalizar.', null, true, 'public', 'published'),
  ('c1500000-0000-4000-8000-000000000006', 'custom_content', 'Chamada final', 'Bloco de encerramento com mensagem curta e ação principal antes do contato ou rodapé.', null, true, 'public', 'published'),
  ('c1500000-0000-4000-8000-000000000007', 'custom_content', 'Linha do tempo', 'Marcos da trajetória apresentados em sequência, sem exigir configuração técnica de grid.', null, true, 'public', 'published')
